```bash
cat <<'EOF' > none_tzname_test.py
from datetime import datetime, tzinfo, timedelta
import arrow

# Create a custom timezone class that returns None for tzname
class CustomTimezone(tzinfo):
    def utcoffset(self, dt):
        return timedelta(hours=-5)

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return None

# Test with our custom timezone
custom_tz = CustomTimezone()
dt = datetime(2023, 1, 15, 12, 0, tzinfo=custom_tz)

print("Custom timezone with tzname() returning None:")
print("Datetime object tzname():", dt.tzname())
try:
    result = arrow.get(dt).format('ZZZ')
    print("Arrow ZZZ format:", result)
except Exception as e:
    print("Arrow ZZZ format failed:", e)
EOF
```

